14	func TestFetchURL(t *testing.T) {
15		tests := []struct {
16			name         string
17			originURL    string
18			settingsJSON string
19			token        string
20			wantURL      string
21			wantErr      bool
22		}{
23			{
24				name:         "checkpoint remote with token and https origin returns https checkpoint url",
25				originURL:    "https://github.com/acme/app.git",
26				settingsJSON: `{"enabled":true,"strategy_options":{"checkpoint_remote":{"provider":"github","repo":"acme/checkpoints"}}}`,
27				token:        "secret-token",
28				wantURL:      "https://github.com/acme/checkpoints.git",
29			},
30			{
31				name:         "checkpoint remote with token and ssh origin returns https checkpoint url",
32				originURL:    "git@github.com:acme/app.git",
33				settingsJSON: `{"enabled":true,"strategy_options":{"checkpoint_remote":{"provider":"github","repo":"acme/checkpoints"}}}`,
34				token:        "secret-token",
35				wantURL:      "https://github.com/acme/checkpoints.git",
36			},
37			{
38				name:         "checkpoint remote without token and https origin reuses https",
39				originURL:    "https://github.com/acme/app.git",
40				settingsJSON: `{"enabled":true,"strategy_options":{"checkpoint_remote":{"provider":"github","repo":"acme/checkpoints"}}}`,
41				wantURL:      "https://github.com/acme/checkpoints.git",
42			},
43			{
44				name:         "checkpoint remote without token and ssh origin reuses ssh",
45				originURL:    "git@github.com:acme/app.git",
46				settingsJSON: `{"enabled":true,"strategy_options":{"checkpoint_remote":{"provider":"github","repo":"acme/checkpoints"}}}`,
47				wantURL:      "git@github.com:acme/checkpoints.git",
48			},
49			{
50				name:         "no checkpoint remote with https origin returns origin url",
51				originURL:    "https://github.com/acme/app.git",
52				settingsJSON: `{"enabled":true}`,
53				wantURL:      "https://github.com/acme/app.git",
54			},
55			{
56				name:         "no checkpoint remote with ssh origin returns origin url",
57				originURL:    "git@github.com:acme/app.git",
58				settingsJSON: `{"enabled":true}`,
59				wantURL:      "git@github.com:acme/app.git",
60			},
61		}
62	
63		for _, tt := range tests {
64			t.Run(tt.name, func(t *testing.T) {
65				repoDir := t.TempDir()
66				testutil.InitRepo(t, repoDir)
67				runGit(t, repoDir, "remote", "add", "origin", tt.originURL)
68				writeSettings(t, repoDir, tt.settingsJSON)
69				t.Chdir(repoDir)
70				if tt.token != "" {
71					t.Setenv(checkpointTokenEnvVar, tt.token)
72				}
73	
74				got, err := FetchURL(context.Background())
75				if tt.wantErr {
76					if err == nil {
77						t.Fatal("FetchURL() error = nil, want error")
78					}
79					return
80				}
81				if err != nil {
82					t.Fatalf("FetchURL() error = %v", err)
83				}
84				if got != tt.wantURL {
85					t.Fatalf("FetchURL() = %q, want %q", got, tt.wantURL)
86				}
87			})
88		}
89	}
