102	func TestFetchURL_EdgeCases(t *testing.T) {
103		tests := []struct {
104			name         string
105			addOrigin    bool
106			originURL    string
107			settingsJSON string
108			token        string
109			wantURL      string
110			wantErr      bool
111		}{
112			{
113				name:         "unsupported origin protocol without token falls back to origin",
114				addOrigin:    true,
115				settingsJSON: `{"enabled":true,"strategy_options":{"checkpoint_remote":{"provider":"github","repo":"acme/checkpoints"}}}`,
116				wantURL:      "",
117			},
118			{
119				name:         "unsupported origin protocol with token returns https checkpoint url",
120				addOrigin:    true,
121				settingsJSON: `{"enabled":true,"strategy_options":{"checkpoint_remote":{"provider":"github","repo":"acme/checkpoints"}}}`,
122				token:        "secret-token",
123				wantURL:      "https://github.com/acme/checkpoints.git",
124			},
125			{
126				name:         "missing origin with token returns https checkpoint url",
127				settingsJSON: `{"enabled":true,"strategy_options":{"checkpoint_remote":{"provider":"github","repo":"acme/checkpoints"}}}`,
128				token:        "secret-token",
129				wantURL:      "https://github.com/acme/checkpoints.git",
130			},
131			{
132				name:         "malformed settings with token falls back to origin because checkpoint remote config is unavailable",
133				addOrigin:    true,
134				settingsJSON: `{`,
135				token:        "secret-token",
136				wantURL:      "",
137			},
138			{
139				name:         "malformed settings with token and ssh origin returns https origin url",
140				originURL:    "git@github.com:acme/app.git",
141				settingsJSON: `{`,
142				token:        "secret-token",
143				wantURL:      "https://github.com/acme/app.git",
144			},
145		}
146	
147		for _, tt := range tests {
148			t.Run(tt.name, func(t *testing.T) {
149				repoDir := t.TempDir()
150				testutil.InitRepo(t, repoDir)
151	
152				originURL := tt.originURL
153				if tt.addOrigin {
154					originDir := t.TempDir()
155					initBareRepo(t, originDir)
156					originURL = fileURL(originDir)
157				}
158				if originURL != "" {
159					runGit(t, repoDir, "remote", "add", "origin", originURL)
160				}
161	
162				writeSettings(t, repoDir, tt.settingsJSON)
163				t.Chdir(repoDir)
164				if tt.token != "" {
165					t.Setenv(checkpointTokenEnvVar, tt.token)
166				}
167	
168				got, err := FetchURL(context.Background())
169				if tt.wantErr {
170					if err == nil {
171						t.Fatal("FetchURL() error = nil, want error")
172					}
173					return
174				}
175				if err != nil {
176					t.Fatalf("FetchURL() error = %v", err)
177				}
178	
179				wantURL := tt.wantURL
180				if wantURL == "" {
181					wantURL = originURL
182				}
183				if got != wantURL {
184					t.Fatalf("FetchURL() = %q, want %q", got, wantURL)
185				}
186			})
187		}
188	}
