190	func TestPushURL(t *testing.T) {
191		tests := []struct {
192			name         string
193			originURL    string
194			pushRemote   string
195			pushURL      string
196			settingsJSON string
197			token        string
198			wantURL      string
199			wantEnabled  bool
200			wantErr      bool
