104	// PushURL returns the effective checkpoint push URL for the current repository.
105	// Unlike FetchURL:
106	//   - it derives protocol from the requested push remote, not always origin
107	//   - it skips checkpoint remote use when the push remote owner differs
108	//     from the configured checkpoint remote owner
109	//
110	// If ENTIRE_CHECKPOINT_TOKEN is set, HTTPS is forced so the token can be used
111	// even when the push remote is configured via SSH.
112	//
113	// The boolean return value reports whether a dedicated checkpoint_remote is
114	// configured and should be used for push. When false, the returned URL is the
115	// repository's origin URL as a fallback.
116	func PushURL(ctx context.Context, pushRemoteName string) (string, bool, error) {
117		originURL := ""
118		if resolvedOriginURL, err := GetRemoteURL(ctx, originRemote); err == nil {
119			originURL = resolvedOriginURL
120		}
121	
122		s, err := settings.Load(ctx)
123		if err != nil {
124			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
125			if fallbackErr == nil {
126				logFallback(ctx, "push", fallbackURL, "load settings", err,
127					slog.String("push_remote", pushRemoteName),
128				)
129				return fallbackURL, false, nil
130			}
131			return "", false, fmt.Errorf("load settings: %w", err)
132		}
133	
134		config := s.GetCheckpointRemote()
135		if config == nil {
136			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
137			if fallbackErr != nil {
138				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
139			}
140			return fallbackURL, false, nil
141		}
142	
143		pushRemoteURL, err := GetRemoteURL(ctx, pushRemoteName)
144		if err != nil {
145			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
146			if fallbackErr == nil {
147				logFallback(ctx, "push", fallbackURL, "get push remote URL", err,
148					slog.String("push_remote", pushRemoteName),
149				)
150				return fallbackURL, false, nil
151			}
152			return "", true, fmt.Errorf("no push URL found: %w", err)
153		}
154	
155		pushInfo, err := ParseURL(pushRemoteURL)
156		if err != nil {
157			if originURL != "" {
158				logFallback(ctx, "push", originURL, "parse push remote URL", err,
159					slog.String("push_remote", pushRemoteName),
160				)
161				return originURL, false, nil
162			}
163			return "", true, fmt.Errorf("no push URL found: %w", err)
164		}
165		if strings.TrimSpace(os.Getenv(checkpointTokenEnvVar)) != "" {
166			pushInfo = &Info{
167				Protocol: ProtocolHTTPS,
168				Host:     pushInfo.Host,
169				Owner:    pushInfo.Owner,
170				Repo:     pushInfo.Repo,
171			}
172		}
173	
174		checkpointOwner := config.Owner()
175		if pushInfo.Owner != "" && checkpointOwner != "" && !strings.EqualFold(pushInfo.Owner, checkpointOwner) {
176			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
177			if fallbackErr != nil {
178				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
179			}
180			return fallbackURL, false, nil
181		}
182	
183		pushURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
184		if err != nil {
185			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
186			if fallbackErr == nil {
187				logFallback(ctx, "push", fallbackURL, "derive push checkpoint URL", err,
188					slog.String("push_remote", pushRemoteName),
189				)
190				return fallbackURL, false, nil
191			}
192			return "", true, fmt.Errorf("no push URL found: %w", err)
193		}
194	
195		return pushURL, true, nil
196	}
